// Reference solution
function contractDiff(oldShape, newShape) {
  const out = [];
  for (const k of Object.keys(oldShape).sort()) {
    if (!(k in newShape)) out.push(`removed:${k}`);
    else if (oldShape[k] !== newShape[k]) out.push(`type:${k}:${oldShape[k]}->${newShape[k]}`);
  }
  return out;
}

